package com.kuaixietech.integration;
import java.net.*;
import java.net.http.*;
import java.time.Duration;
import java.util.*;
import org.springframework.stereotype.Component;
@Component
public class IntegrationHttp {
 private final HttpClient client;private final Set<String> hosts=new HashSet<>();
 public IntegrationHttp(){var b=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).followRedirects(HttpClient.Redirect.NEVER);String proxy=System.getenv("HTTPS_PROXY");if(proxy!=null&&!proxy.isBlank()){var u=URI.create(proxy);b.proxy(ProxySelector.of(new InetSocketAddress(u.getHost(),u.getPort()<0?80:u.getPort())));}client=b.build();for(String h:System.getenv().getOrDefault("INTEGRATION_API_ALLOWED_HOSTS","").split(","))if(!h.isBlank())hosts.add(h.trim().toLowerCase(Locale.ROOT));}
 public URI endpoint(String value,boolean official){try{URI u=URI.create(value);if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null||u.getPort()!=-1&&u.getPort()!=443)throw new IllegalArgumentException();if(!official&&!hosts.contains(u.getHost().toLowerCase(Locale.ROOT)))throw new IllegalArgumentException();return u;}catch(Exception e){throw new IllegalArgumentException("INTEGRATION_ENDPOINT_REJECTED");}}
 public void delete(java.net.http.HttpRequest request){try{var response=client.send(request,HttpResponse.BodyHandlers.ofInputStream());try(var body=response.body()){if(response.statusCode()==204||response.statusCode()==404)return;if(response.statusCode()==200&&body.read()==-1)return;throw new IllegalStateException("STORAGE_DELETE_UNCONFIRMED");}}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("STORAGE_DELETE_UNCONFIRMED");}catch(Exception e){throw new IllegalStateException("STORAGE_DELETE_UNCONFIRMED");}}
 public String write(HttpRequest request){try{var response=client.send(request,HttpResponse.BodyHandlers.ofInputStream());try(var body=response.body()){if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException();return response.headers().firstValue("ETag").orElseThrow();}}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("UPLOAD_REQUEST_UNCONFIRMED");}catch(Exception e){throw new IllegalStateException("UPLOAD_REQUEST_UNCONFIRMED");}}
 public byte[] read(HttpRequest request,int limit){try{var response=client.send(request,HttpResponse.BodyHandlers.ofInputStream());try(var body=response.body()){if(response.statusCode()!=200)throw new IllegalStateException();byte[] bytes=body.readNBytes(limit+1);if(bytes.length>limit)throw new IllegalStateException();return bytes;}}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("UPLOAD_REQUEST_UNCONFIRMED");}catch(Exception e){throw new IllegalStateException("UPLOAD_REQUEST_UNCONFIRMED");}}
 public String send(HttpRequest request){try{var response=client.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()<200||response.statusCode()>=300||response.body().length()>1_000_000)throw new IllegalStateException();return response.body();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("INTEGRATION_REQUEST_UNCONFIRMED");}catch(Exception e){throw new IllegalStateException("INTEGRATION_REQUEST_UNCONFIRMED");}}
}
